#include <iostream>
#include <vector>
#include <string>
#include <algorithm>
using namespace std;

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    long long m;
    cin >> m;
    vector<vector<long long>> edges(m, vector<long long>(2));
    for (int i = 0; i < m; i++) {
        for (int j = 0; j < 2; j++) {
            cin >> edges[i][j];
        }
    }

    int count = (int)m + 1;
    vector<vector<int>> adj(count + 1);
    for (const vector<long long>& e : edges) {
        adj[e[0]].push_back((int)e[1]);
        adj[e[1]].push_back((int)e[0]);
    }
    vector<int> degree(count + 1, 0);
    for (int v = 1; v <= count; v++) degree[v] = (int)adj[v].size();
    vector<int> leaves;
    for (int v = 1; v <= count; v++) {
        if (degree[v] <= 1) leaves.push_back(v);
    }
    int remaining = count;
    while (remaining > 2) {
        remaining -= (int)leaves.size();
        vector<int> next;
        for (int leaf : leaves) {
            for (int w : adj[leaf]) {
                degree[w]--;
                if (degree[w] == 1) next.push_back(w);
            }
        }
        leaves = next;
    }
    sort(leaves.begin(), leaves.end());
    for (size_t i = 0; i < leaves.size(); i++) cout << (i ? " " : "") << leaves[i];
    cout << "\n";

    return 0;
}

